<?php declare(strict_types=1);require __DIR__.'/../includes/auth.php';$token=(string)($_GET['token']??$_POST['token']??'');$hash=hash('sha256',$token);$s=db()->prepare('SELECT t.*,u.email FROM password_reset_tokens t JOIN admin_users u ON u.id=t.admin_user_id WHERE t.token_hash=? AND t.used_at IS NULL AND t.expires_at>NOW()');$s->execute([$hash]);$row=$s->fetch();$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&$row){if(!csrf_check($_POST['csrf_token']??'')){$error='Your session expired. Please reload the page and try again.';}else{$p=$_POST['password']??'';$c=$_POST['confirm_password']??'';if(strlen($p)<10)$error='Use at least 10 characters.';elseif($p!==$c)$error='Passwords do not match.';else{db()->beginTransaction();db()->prepare('UPDATE admin_users SET password_hash=? WHERE id=?')->execute([password_hash($p,PASSWORD_DEFAULT),$row['admin_user_id']]);db()->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE id=?')->execute([$row['id']]);db()->commit();header('Location:login.php?reset=1');exit;}}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="../assets/design-system.css"><title>Reset Password</title></head><body class="admin-body"><main class="admin-login"><form method="post" class="admin-card admin-login-card"><h1>Choose New Password</h1><?php if(!$row):?><div class="status error">This reset link is invalid or expired.</div><a class="admin-forgot-link" href="forgot_password.php">Request another link</a><?php else:?><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php if($error):?><div class="status error"><?=e($error)?></div><?php endif;?><label>New Password</label><input type="password" name="password" minlength="10" required><label>Confirm Password</label><input type="password" name="confirm_password" minlength="10" required><button class="primary admin-login-button">Update Password</button><?php endif;?></form></main></body></html>